(()=>{let t=(()=>{let t=document.querySelectorAll(".article-detail__content figure");return{setEventClick:function(){t.forEach(t=>{t.addEventListener("click",t=>{var e=t.target.dataset.event;try{this[""+e](t.target)}catch(t){console.log("error: ",t)}})})},setWidthAsContainer:e=>{t.forEach(t=>{t.style.width=window.outerWidth-e+"px"})},addCopylink:()=>{t.forEach(t=>{t.insertAdjacentHTML("afterbegin",'<div class="article-detail__content_copylink" data-event="сopyCode">копировать</div>')})},"сopyCode":t=>{t=t.parentElement.querySelector(".hljs").innerText;navigator.clipboard.writeText(t).then(function(){console.log("Текст успешно скопирован в буфер обмена!")}).catch(function(t){console.error("Ошибка при копировании текста: ",t)})}}})();document.addEventListener("DOMContentLoaded",function(){hljs.highlightAll(),document.querySelectorAll(".btn.btn__back--l-arrow").forEach(t=>{t.addEventListener("click",()=>{var t=document.referrer;t?window.location.href=t:window.history.back()})}),t.setEventClick(),t.addCopylink(),window.outerWidth<=870&&576<window.outerWidth?t.setWidthAsContainer(90):window.outerWidth<=576&&t.setWidthAsContainer(30),window.addEventListener("resize",()=>{window.outerWidth<=870&&576<window.outerWidth?t.setWidthAsContainer(90):window.outerWidth<=576&&t.setWidthAsContainer(30)})})})();